#include "amichat_json.h"
#include <stddef.h>
#include <string.h>
static int ac(char*b,size_t c,size_t*l,char x){if(!b||!l||*l+1>=c)return 0;b[(*l)++]=x;b[*l]='\0';return 1;}
static int ah(char*b,size_t c,size_t*l,unsigned char v){static const char h[]="0123456789abcdef";return ac(b,c,l,h[(v>>4)&15])&&ac(b,c,l,h[v&15]);}
AmiChatResult AmiChat_JSONAppendString(char*b,size_t c,size_t*l,const char*v){const unsigned char*p;if(!b||!l||!v||*l>=c)return AMICHAT_ERR_INVALID_ARGUMENT;if(!ac(b,c,l,'"'))return AMICHAT_ERR_NOMEM;for(p=(const unsigned char*)v;*p;++p){if(*p=='"'||*p=='\\'){if(!ac(b,c,l,'\\')||!ac(b,c,l,(char)*p))return AMICHAT_ERR_NOMEM;}else if(*p<0x20){if(!ac(b,c,l,'\\'))return AMICHAT_ERR_NOMEM;switch(*p){case '\b':if(!ac(b,c,l,'b'))return AMICHAT_ERR_NOMEM;break;case '\f':if(!ac(b,c,l,'f'))return AMICHAT_ERR_NOMEM;break;case '\n':if(!ac(b,c,l,'n'))return AMICHAT_ERR_NOMEM;break;case '\r':if(!ac(b,c,l,'r'))return AMICHAT_ERR_NOMEM;break;case '\t':if(!ac(b,c,l,'t'))return AMICHAT_ERR_NOMEM;break;default:if(!ac(b,c,l,'u')||!ac(b,c,l,'0')||!ac(b,c,l,'0')||!ah(b,c,l,*p))return AMICHAT_ERR_NOMEM;break;}}else if(!ac(b,c,l,(char)*p))return AMICHAT_ERR_NOMEM;}return ac(b,c,l,'"')?AMICHAT_OK:AMICHAT_ERR_NOMEM;}
const char *AmiChat_JSONFindString(const char*json,const char*key,char*b,size_t c){char needle[128];size_t n=0,i=0;const char*p,*q;if(!json||!key||!b||!c)return 0;if(AmiChat_JSONAppendString(needle,sizeof(needle),&n,key)!=AMICHAT_OK)return 0;p=strstr(json,needle);if(!p)return 0;p+=n;while(*p&&*p!=':')p++;if(!*p)return 0;p++;while(*p==' '||*p=='\t'||*p=='\r'||*p=='\n')p++;if(*p!='"')return 0;p++;q=p;while(*q&&*q!='"'){if(*q=='\\'&&q[1])q++;q++;}if(*q!='"')return 0;while(p<q&&i+1<c){if(*p=='\\'&&p+1<q){p++;switch(*p){case 'n':b[i++]='\n';break;case 'r':b[i++]='\r';break;case 't':b[i++]='\t';break;default:b[i++]=*p;break;}p++;}else b[i++]=*p++;}b[i]='\0';return b;}
